package org.apache.commons.math3.optimization.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MaxCountExceededException;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for SimplexSolver.solvePhase1.
 * Since solvePhase1 is protected, we use a TestSpy or a subclass to access it.
 */
public class SimplexSolver_solvePhase1_TriageGen2Test {

    private SimplexSolver solver;
    private SimplexTableau tableau;
    private static final double EPSILON = 1e-10;

    // Subclass to expose the protected method for testing
    private static class TestableSimplexSolver extends SimplexSolver {
        public TestableSimplexSolver() {
            super();
        }

        @Override
        public void solvePhase1(SimplexTableau tableau) throws MaxCountExceededException, UnboundedSolutionException, NoFeasibleSolutionException {
            super.solvePhase1(tableau);
        }
    }

    @Before
    public void setUp() {
        solver = new TestableSimplexSolver();
        tableau = mock(SimplexTableau.class);
    }

    /**
     * Test Case 1: Branch coverage for the early return when numArtificialVariables is 0.
     */
    @Test
    public void testSolvePhase1_NoArtificialVariables_ReturnsImmediately() throws Exception {
        when(tableau.getNumArtificialVariables()).thenReturn(0);

        solver.solvePhase1(tableau);

        // Verify no iterations were performed
        verify(tableau, never()).isOptimal();
        verify(tableau, never()).getEntry(anyInt(), anyInt());
    }

    /**
     * Test Case 2: Successful Phase 1 completion (W is zero).
     * Covers the while loop and the successful path.
     */
    @Test
    public void testSolvePhase1_SuccessfulPhase1() throws Exception {
        when(tableau.getNumArtificialVariables()).thenReturn(1);
        // First call is not optimal, second call is optimal
        when(tableau.isOptimal()).thenReturn(false, true);
        // Simulate W (objective value of artificials) being 0
        int rhsOffset = 5;
        when(tableau.getRhsOffset()).thenReturn(rhsOffset);
        when(tableau.getEntry(0, rhsOffset)).thenReturn(0.0);

        // We need to mock the behavior of the solver itself if it calls doIteration
        // However, since doIteration is a method within the same class, 
        // we use a spy to avoid real logic execution of doIteration if it's complex.
        TestableSimplexSolver spySolver = spy(new TestableSimplexSolver());
        doNothing().when(spySolver).doIteration(tableau);

        // Re-mocking tableau for the spy context
        when(tableau.getNumArtificialVariables()).thenReturn(1);
        when(tableau.isOptimal()).thenReturn(false, true);
        when(tableau.getEntry(0, rhsOffset)).thenReturn(0.0);
        when(tableau.getRhsOffset()).thenReturn(rhsOffset);

        spySolver.solvePhase1(tableau);

        verify(spySolver, times(1)).doIteration(tableau);
        verify(tableau, never()).getEntry(anyInt(), anyInt()); // Wait, the code calls getEntry at the end
        verify(tableau).getEntry(0, rhsOffset);
    }

    /**
     * Test Case 3: No Feasible Solution (W is not zero).
     * Covers the exception throwing path.
     */
    @Test(expected = NoFeasibleSolutionException.class)
    public void testSolvePhase1_NoFeasibleSolution() throws Exception {
        when(tableau.getNumArtificialVariables()).thenReturn(1);
        when(tableau.isOptimal()).thenReturn(true);

        int rhsOffset = 5;
        when(tableau.getRhsOffset()).thenReturn(rhsOffset);
        // W is non-zero
        when(tableau.getEntry(0, rhsOffset)).thenReturn(0.5);

        solver.solvePhase1(tableau);
    }

    /**
     * Test Case 4: MaxCountExceededException during iteration.
     * Covers the exception propagation from doIteration.
     */
    @Test(expected = MaxCountExceededException.class)
    public void testSolvePhase1_MaxCountExceeded() throws Exception {
        when(tableau.getNumArtificialVariables()).thenReturn(1);
        when(tableau.isOptimal()).thenReturn(false);

        TestableSimplexSolver spySolver = spy(new TestableSimplexSolver());
        doThrow(new MaxCountExceededException()).when(spySolver).doIteration(tableau);

        spySolver.solvePhase1(tableau);
    }

    /**
     * Test Case 5: UnboundedSolutionException during iteration.
     * Covers the exception propagation from doIteration.
     */
    @Test(expected = UnboundedSolutionException.class)
    public void testSolvePhase1_UnboundedSolution() throws Exception {
        when(tableau.getNumArtificialVariables()).thenReturn(1);
        when(tableau.isOptimal()).thenReturn(false);

        TestableSimplexSolver spySolver = spy(new TestableSimplexSolver());
        doThrow(new UnboundedSolutionException()).when(spySolver).doIteration(tableau);

        spySolver.solvePhase1(tableau);
    }
}
